    detail:{ 关键词:['灵能','恶魔','审判庭','秘密'],
      说明:'灰骑士是帝皇在叛乱末期亲自筹划的「恶魔猎人」战团，全员皆为强力灵能者。他们身着祝福过的银色动力甲，以灵能武器与恶魔真名对抗亚空间实体。',
      使命:'灰骑士专责阻止恶魔入侵现实、猎杀被附身者、封印亚空间裂隙。他们不出现在常规战场上，只在最可怕的恶魔威胁降临时现身，以极端手段确保秘密不泄露。',
      隐秘:'由于凡人知晓恶魔存在即可能被腐化，灰骑士行动后常以审判庭名义抹除目击者记忆、销毁证据。许多帝国公民终生不知这支银色战团的存在，它是帝国对抗亚空间阴影的最后一道防线。'}
