    detail:{ 关键词:['基里曼','重连','原铸','远征'],
      说明:'不屈远征是原体罗伯特·基里曼从大裂隙的废墟中苏醒后发起的大规模反攻与救援行动。其目标是在帝国被亚空间风暴撕裂后，重连失落世界、击退入侵者并稳定战线。',
      发起:'基里曼身为奥特拉玛之主与帝国摄政，发现帝国已经僵化腐朽、四分五裂。他以原体权威推动改革，集结舰队从泰拉出发，向银河各方向同时推进。',
      意义:'远征不仅拯救了无数即将陷落的世界，还大规模列装经贝利萨留·考尔改良的「原铸星际战士」。这批新兵种的加入，使帝国在持续恶化的银河局势中重新获得战略主动权。'}
